CREATE OR REPLACE FUNCTION private.dic_admin_review_signup(p_member_id uuid, p_action text, p_expected_state text DEFAULT 'pending'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); member private.beta_members; verified boolean;
begin
 perform private.require_member();
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator required.';
 end if;
 if p_member_id is null or p_member_id=actor or p_action is null or p_action not in ('approve','reject')
  or p_expected_state is distinct from 'pending' then
  raise exception using errcode='22023',message='Invalid signup review.';
 end if;
 if exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator protected.';
 end if;
 select * into member from private.beta_members where owner_id=p_member_id for update;
 if not found then
  raise exception using errcode='22023',message='Account unavailable.';
 end if;
 -- A repeat click or concurrent reviewer must be safely rejected as stale.
 if member.signup_review_state <> p_expected_state or
    member.admitted_at is not null or member.enabled then
  return jsonb_build_object('ok',false,'code','stale_review');
 end if;
 select u.email_confirmed_at is not null into verified
 from auth.users u where u.id=p_member_id;
 if p_action='approve' and verified is distinct from true then
  return jsonb_build_object('ok',false,'code','verify_email_first');
 end if;
 update private.beta_members set
   signup_review_state=case when p_action='approve' then 'approved' else 'rejected' end,
   enabled=(p_action='approve'),
   admitted_at=case when p_action='approve' then now() else null end
 where owner_id=p_member_id;
 insert into private.dic_signup_review_events(member_id,actor_id,action,previous_state)
 values(p_member_id,actor,p_action,member.signup_review_state);
 return jsonb_build_object('ok',true,'decision',p_action,'member_id',p_member_id);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_set_member_access(p_member_id uuid, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();m private.beta_members;found_member uuid;
begin
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator access required.';
 end if;
 if p_member_id is null or p_enabled is null then
  raise exception using errcode='22023',message='Member and desired access are required.';
 end if;
 -- Never allow an administrator to revoke themself OR ANY administrator.
 -- The underlying permanent admin role has no expiration.
 if p_member_id=actor or exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator accounts cannot be removed here.';
 end if;
 -- Permanently deleting a member supersedes reversible Restore/Remove.
 if exists(select 1 from private.dic_admin_account_delete_operations
   where target_id=p_member_id and phase<>'completed') then
  raise exception using errcode='23514',message='Permanent deletion is underway; finish it before changing access.';
 end if;
 select * into m from private.beta_members where owner_id=p_member_id for update;
 if not found or m.admitted_at is null then
  raise exception using errcode='22023',message='Only previously admitted members can be changed.';
 end if;
 if p_enabled and not exists(select 1 from auth.users where id=p_member_id and email_confirmed_at is not null) then
  raise exception using errcode='42501',message='Verified email required.';
 end if;
 if m.enabled=p_enabled then
  return jsonb_build_object('ok',true,'enabled',p_enabled,'unchanged',true);
 end if;
 update private.beta_members set enabled=p_enabled
 where owner_id=p_member_id returning owner_id into found_member;
 insert into private.admin_access_events(actor_id,action,member_id)
 values(actor,case when p_enabled then 'restore_access' else 'remove_access' end,found_member);
 -- No auth.users deletion, note deletion, contribution identity reidentification,
 -- historical mutation, or implicit sign-out of already issued Supabase tokens.
 -- All member RPCs and RLS must recheck private.is_member().
 return jsonb_build_object('ok',true,'enabled',p_enabled);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_signup_requests(p_offset integer DEFAULT 0, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare total bigint; listing jsonb;
begin
 perform private.require_member();
 if auth.uid() is null or not private.is_admin() then
  raise exception using errcode='42501', message='Administrator required.';
 end if;
 if p_offset is null or p_offset<0 or p_offset>1000000
    or p_limit is null or p_limit<1 or p_limit>50 then
  raise exception using errcode='22023',message='Invalid paging.';
 end if;
 select count(*) into total from private.beta_members m
 where m.admitted_at is null and m.signup_review_state='pending';
 select coalesce(jsonb_agg(v.record order by v.created_at,v.id),'[]'::jsonb) into listing
 from (select m.owner_id as id,u.created_at,
   jsonb_build_object(
    'id',m.owner_id,'email',left(coalesce(u.email,''),254),
    'created_at',u.created_at,'email_verified',u.email_confirmed_at is not null,
    'review_state',m.signup_review_state
   ) as record
   from private.beta_members m join auth.users u on u.id=m.owner_id
   where m.admitted_at is null and m.signup_review_state='pending'
   order by u.created_at,m.owner_id limit p_limit offset p_offset) v;
 return jsonb_build_object('total',total,'offset',p_offset,'items',coalesce(listing,'[]'::jsonb));
end $function$
